from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='La membrana plasmática separa el interior de la célula del medio exterior y controla lo que entra y sale. Este capítulo explica su estructura de bicapa lipídica, cómo se llegó a ella, cómo la bomba de sodio y potasio crea gradientes de iones y cómo la ecuación de Nernst relaciona esos gradientes con el potencial de membrana.',
        quotes=[Q('es_membrana','es una capa o bicapa lipídica de fosfolípidos y otras sustancias que delimita toda la célula'), Q('en_membrane','The cell membrane controls the movement of substances in and out of a cell, being selectively permeable to ions and organic molecules.')]))
    P.append(dict(text='La membrana plasmática es una bicapa lipídica formada sobre todo por fosfolípidos, que son anfipáticos: tienen una cabeza fosfato hidrofílica y colas hidrofóbicas, y por eso se agrupan en capas sin aporte de energía. Los lípidos de membrana son insolubles en agua. Las membranas de eucariotas y de algunas arqueas contienen además esteroles, como el colesterol en los animales, que mantienen una fluidez adecuada a distintas temperaturas.',
        quotes=[Q('es_membrana','los glicerofosfolípidos son, con mucho, los lípidos más abundantes en las membranas celulares'), Q('es_membrana','su geometría única hace que se agreguen en capas sin ningún aporte de energía'), Q('en_membrane','eukaryotes and some archaea typically have sterols (such as cholesterol in animals) interspersed between them as well, maintaining appropriate membrane fluidity at various temperatures')]))
    P.append(dict(text='La membrana contiene también proteínas. Las proteínas integrales atraviesan la membrana y actúan como transportadores; las periféricas se unen a su superficie y actúan como enzimas. Entre las funciones de la membrana están la protección de la célula, el anclaje del citoesqueleto, la semipermeabilidad, la ósmosis para la difusión pasiva de solutos y la unión entre células mediante proteínas especializadas, como las cadherinas, que forman tejidos.',
        quotes=[Q('en_membrane','including integral proteins that span the membrane and serve as transporters, and peripheral proteins that attach to the surface of the cell membrane, acting as enzymes'), Q('es_membrana','Semipermeabilidad, para el intercambio de sustancias.'), Q('es_membrana','La membrana permite la unión entre células mediante proteínas especializadas (como las cadherinas), formando tejidos')]))
    P.append(dict(text='La membrana no se conoció de golpe. En 1895 Ernest Overton propuso que las membranas celulares estaban hechas de lípidos. En 1925 Gorter y Grendel extrajeron los lípidos de glóbulos rojos humanos, midieron la superficie que cubrían al extenderlos sobre agua y compararon esa superficie con la de las células de las que procedían: la razón fue de aproximadamente 2 a 1, de lo que concluyeron que la membrana contiene una bicapa lipídica. Eligieron los glóbulos rojos porque no tienen orgánulos membranosos que interfieran con el análisis.',
        quotes=[Q('en_membrane','In 1895, Ernest Overton proposed that cell membranes were made of lipids.'), Q('en_membrane','The ratio of the surface area of water covered by the extracted lipid to the surface area calculated for the red blood cells from which the lipid was 2:1(approx) and they concluded that the plasma membrane contains a lipid bilayer.'), Q('es_membrana','escogieron a los glóbulos rojos debido a que estos no poseen ningún orgánulo membranoso que interfiera con el análisis')]))
    P.append(dict(text='Las fuentes dan una medida aproximada del grosor de la membrana de 7,4 nm (74 Å), demasiado pequeña para verse con el microscopio óptico pero visible con el electrónico. La otra fuente recoge una medida histórica distinta: en 1925 se determinó que el grosor de las membranas de eritrocitos y de levaduras estaba entre 3,3 y 4 nm, compatible con una monocapa lipídica. La fuente en inglés añade que la elección de la constante dieléctrica usada en aquellos estudios fue puesta en duda, y presenta la medida como parte de la historia de la discusión sobre la bicapa, no como una estimación actual.',
        quotes=[Q('es_membrana','Tiene una medida aproximada de 7,4 nm','no es visible al microscopio óptico, pero sí al microscopio electrónico'), Q('en_membrane','the thickness of erythrocyte and yeast cell membranes ranged between 3.3 and 4 nm, a thickness compatible with a lipid monolayer'), Q('en_membrane','The choice of the dielectric constant used in these studies was called into question')]))
    P.append(dict(text='Muchas sustancias necesitan transporte activo, que consume energía. La bomba de sodio y potasio, o Na+/K+-ATPasa, es una enzima que se encuentra en la membrana plasmática de todas las células animales. Por cada molécula de ATP que usa, exporta tres iones de sodio e importa dos de potasio, de modo que cada ciclo saca una carga positiva neta. El efecto es una concentración extracelular de sodio cinco veces mayor que la intracelular y una concentración intracelular de potasio treinta veces mayor que la extracelular.',
        quotes=[Q('es_bomba','La bomba expulsa tres iones sodio (Na+) hacia la matriz extracelular a la vez que ingresa dos iones potasio (K+) hacia el citoplasma'), Q('en_pump','For every ATP molecule that the pump uses, three sodium ions are exported and two potassium ions are imported.'), Q('en_pump','The net effect is an extracellular concentration of sodium ions 5 times the intracellular concentration, and an intracellular concentration of potassium ions 30 times the extracellular concentration.')]))
    P.append(dict(text='La bomba fue descubierta en 1957 por el científico danés Jens Christian Skou, que recibió el Premio Nobel en 1997. Mantiene el potencial de reposo, interviene en el transporte y regula el volumen celular. Es responsable de mantener las diferencias de concentración de sodio y de potasio a través de la membrana y de establecer un voltaje eléctrico negativo en el interior de las células. Es una ATPasa de tipo P: sufre fosforilaciones reversibles durante el transporte.',
        quotes=[Q('en_pump','The sodium–potassium pump was discovered in 1957 by the Danish scientist Jens Christian Skou, who was awarded a Nobel Prize for his work in 1997.'), Q('es_bomba','así como de establecer un voltaje eléctrico negativo en el interior de las células'), Q('en_pump','The Na+/K+-ATPase helps maintain resting potential, affects transport, and regulates cellular volume.'), Q('es_bomba','Es una ATPasa de transporte tipo P, es decir, sufre fosforilaciones reversibles durante el proceso de transporte.')]))
    P.append(dict(text='La ecuación de Nernst permite calcular el potencial de un ion de carga z a través de una membrana a partir de sus concentraciones dentro y fuera de la célula. Para un ion con una sola especie permeable en equilibrio, el potencial de membrana coincide con su potencial de Nernst. A temperatura ambiente (25 °C) la tensión térmica RT/F vale aproximadamente 25,693 mV. En la célula real, el potencial de membrana se acerca al de Nernst del potasio porque la membrana es muy permeable a ese ion.',
        quotes=[Q('en_nernst','The Nernst equation has a physiological application when used to calculate the potential of an ion of charge z across a membrane.'), Q('en_nernst','the membrane potential must be equal to the Nernst potential for that ion'), Q('en_nernst','is approximately 25.693 mV'), Q('en_pump','thus the voltage across the plasma membrane is close to the Nernst potential of potassium')]))
    P.append(dict(role='definition', text='Transporte activo: transporte de una sustancia a través de la membrana en contra de su gradiente de concentración, que consume energía en forma de ATP. La bomba de sodio y potasio es el ejemplo clásico.',
        quotes=[Q('en_pump','The Na+/K+-ATPase enzyme is an enzyme involved in active transport (i.e. it uses energy from ATP).'), Q('es_bomba','mediante transporte activo que ocupa como fuente de energía el ATP')]))
    P.append(dict(role='consejo', text='Al aplicar la ecuación de Nernst, fije primero el signo: con el ion fuera sobre dentro en el logaritmo, un ion positivo más concentrado dentro que fuera da un potencial negativo. Comprobarlo con el potasio, que está treinta veces más concentrado en el interior, evita errores de signo.',
        quotes=[Q('en_pump','an intracellular concentration of potassium ions 30 times the extracellular concentration'), Q('es_bomba','establecer un voltaje eléctrico negativo en el interior de las células')]))
    P.append(dict(role='self_check', text='¿Por qué la bicapa lipídica se forma sin aporte de energía? ¿Cuántos iones de cada tipo mueve la bomba de sodio y potasio por ATP y qué carga neta exporta? ¿Qué tensión térmica se usa en la ecuación de Nernst a 25 °C?',
        quotes=[Q('es_membrana','se agreguen en capas sin ningún aporte de energía'), Q('en_pump','Thus, there is a net export of a single positive charge per pump cycle.')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Según una fuente, la concentración intracelular de potasio es 30 veces la extracelular. Con una tensión térmica de 25,693 mV a 25 °C y z = +1, calcule el potencial de Nernst del potasio, E = V_T ln([K]fuera/[K]dentro), en milivoltios.',
        expected='-87.4', quotes=[Q('en_pump','an intracellular concentration of potassium ions 30 times the extracellular concentration'), Q('en_nernst','is approximately 25.693 mV')],
        method='Ecuación de Nernst para un ion monovalente',
        solution=dict(given=[dict(symbol='V_T',value=25.693,unit='mV',meaning='tensión térmica RT/F a 25 °C'),dict(symbol='r',value=30,unit='dimensionless',meaning='cociente [K]dentro/[K]fuera'),dict(symbol='z',value=1,unit='dimensionless',meaning='carga del ion potasio')],
          unknown='El potencial de Nernst del potasio.',
          model=[dict(name='Potencial de Nernst',latex='E_{K} = \\frac{V_T}{z}\\,\\ln\\frac{[K]_{\\mathrm{fuera}}}{[K]_{\\mathrm{dentro}}}',symbolic='V_T/z*log(1/r)')],
          assumptions=['La membrana solo es permeable al potasio y está en equilibrio.','Se usan concentraciones en lugar de actividades.'],
          development=['El potasio está 30 veces más concentrado dentro, así que el cociente fuera/dentro es 1/30 y su logaritmo es negativo.'],
          steps=[dict(text='Logaritmo del cociente',equation='\\ln(1/30)',expression='log(1/30)',expected=-3.4012,unit='dimensionless'),
                 dict(text='Potencial de Nernst',equation='E_K = 25{,}693 \\cdot \\ln(1/30)',expression='25.693*log(1/30)',expected=-87.39,unit='mV')],
          result='El potencial de Nernst del potasio es de unos -87,4 mV a 25 °C.',
          interpretation='El valor es negativo porque el potasio sale de la célula siguiendo su gradiente, y es cercano al potencial de reposo de las células animales, que es negativo en el interior.',
          limitations=['A la temperatura corporal de 37 °C la tensión térmica es algo mayor y el potencial cambia en proporción.','El potencial de reposo real también depende de otros iones, como el sodio.'],
          mistakes=['Invertir el cociente de concentraciones, que da un potencial positivo.']))]
